index 27fbc11b..abb48293 100644
--- a/codex-rs/hepta-agentd/src/circuit_evaluated_selection_readback_support_tests.rs
+++ b/codex-rs/hepta-agentd/src/circuit_evaluated_selection_readback_support_tests.rs
@@ -119,15 +119,14 @@ impl<W: AnchorWitnessStore + Send + 'static, C: AnchorWitnessStore + Send + 'sta
                     let response = host
                         .evidence_response(bytes, request_id)
                         .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
-                    if let Some((after, file)) = &invalidate_source_after_read {
-                        if request_id == *after {
+                    if let Some((after, file)) = &invalidate_source_after_read
+                        && request_id == *after {
                             // The actual S response already passed its final
                             // T/B/Cell read. Only C's final Source check sees
                             // this durable original Source becoming unreadable.
                             file.set_len(0)
                                 .map_err(|_| HostIssuerTransportError::Unavailable)?;
                         }
-                    }
                     Ok(response)
                 })? {
                     return Ok(request_id - 1);
